import{_ as i,o as n,c as t,a2 as u}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Jedwali la Jumla la Mgawanyo wa Enzi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/70-纪元划分总表.md","filePath":"sw/70-纪元划分总表.md","lastUpdated":1789183869000}'),d={name:"sw/70-纪元划分总表.md"};function e(o,a,l,w,k,h){return n(),t("div",null,[...a[0]||(a[0]=[u('<h1 id="jedwali-la-jumla-la-mgawanyo-wa-enzi" tabindex="-1">Jedwali la Jumla la Mgawanyo wa Enzi <a class="header-anchor" href="#jedwali-la-jumla-la-mgawanyo-wa-enzi" aria-label="Permalink to &quot;Jedwali la Jumla la Mgawanyo wa Enzi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>70</td></tr><tr><td>Moduli</td><td>Enzi za Kihistoria na Matukio Muhimu</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Mgawanyo wa enzi, mgawanyo wa kihistoria, kupanda kwa viwango vinne, mstari wa muda, alama ya mwenendo</td></tr></tbody></table><h2 id="_1-kanuni-za-msingi-za-mgawanyo-wa-enzi" tabindex="-1">1. Kanuni za Msingi za Mgawanyo wa Enzi <a class="header-anchor" href="#_1-kanuni-za-msingi-za-mgawanyo-wa-enzi" aria-label="Permalink to &quot;1. Kanuni za Msingi za Mgawanyo wa Enzi&quot;">​</a></h2><p>Mgawanyo wa enzi za kihistoria za Hengyuanzhou unachukua njia ya kupanda kwa viwango vinne kama muundo wa msingi, na hali ya maendeleo ya utaratibu wa nanga kama msingi wa kuzingatia mgawanyo. Kila enzi linafanana na mabadiliko ya msingi katika uhusiano kati ya ustaarabu na ulimwengu; mipaka kati ya enzi sio vidokezo vya muda vya hiari, bali vinawekwa alama na matukio muhimu yenye umuhimu wa ulimwengu.</p><p>Mgawanyo wa enzi unafuata kanuni tatu:</p><ul><li><strong>Kanuni ya ufanano wa kupanda</strong>: kila enzi kubwa linafanana na hatua moja katika njia ya kupanda kwa viwango vinne, na vipindi vilivyogawanywa ndani ya enzi vinafanana na maendeleo muhimu ndani ya hatua hiyo</li><li><strong>Kanuni ya kuweka alama kwa matukio</strong>: vidokezo vya kuanza na kumaliza kwa enzi vinabainishwa na matukio muhimu yenye alama, si kwa mgawanyo sawa wa muda rahisi</li><li><strong>Kanuni ya hali ya ustaarabu</strong>: kila enzi linapewa jina kulingana na sifa za msingi za ustaarabu katika kipindi hicho, zinaonyesha utata kuu na mwelekeo wa maendeleo wa wakati huo</li></ul><h2 id="_2-jedwali-la-jumla-la-enzi-za-kihistoria-za-hengyuanzhou" tabindex="-1">2. Jedwali la Jumla la Enzi za Kihistoria za Hengyuanzhou <a class="header-anchor" href="#_2-jedwali-la-jumla-la-enzi-za-kihistoria-za-hengyuanzhou" aria-label="Permalink to &quot;2. Jedwali la Jumla la Enzi za Kihistoria za Hengyuanzhou&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari ya Enzi</th><th>Jina la Enzi</th><th>Hatua ya Kupanda inayofanana</th><th>Matukio ya Alama ya Kuanza-Kumaliza</th><th>Sifa za Msingi</th></tr></thead><tbody><tr><td>Enzi ya Kwanza</td><td>Enzi ya Kabla ya Nanga</td><td>Kabla ya kupanda</td><td>Kuzaliwa kwa ulimwengu→Uamsho wa kizazi cha kwanza cha nanga</td><td>Ulinzi wa mauaji unaotawala, kuteketezwa kwa ustaarabu mara kwa mara</td></tr><tr><td>Enzi ya Pili</td><td>Enzi ya Uamsho wa Nanga</td><td>Mwanzo wa ujenzi wa msingi wa ukweli</td><td>Uamsho wa kizazi cha kwanza cha nanga→Saini ya Hati ya Usirikisho</td><td>Utaratibu wa nanga umeanzishwa, chanzo cha wazo la kupinga mauaji</td></tr><tr><td>Enzi ya Tatu</td><td>Kipindi cha Uanzishaji wa Mfumo wa Usirikisho</td><td>Msingi wa ukweli</td><td>Saini ya Hati ya Usirikisho→Kufunguliwa kwa miitano mia tatu kamili</td><td>Mfumo wa usirikisho umeatekelezwa, ujenzi wa kijamii umekamilika</td></tr><tr><td>Enzi ya Nne</td><td>Enzi ya Kufungua na Kuwasha Mfumo</td><td>Mwanzo wa uwezeshaji wa teknolojia</td><td>Kufunguliwa kwa miitano mia tatu→Kukamilika kwa mkakati wa kuwasha 20%</td><td>Uenezi wa ulinzi, mapambano katika uhandisi wa sheria</td></tr><tr><td>Enzi ya Tano</td><td>Enzi ya Kupanda kwa Mara ya Kwanza</td><td>Uwezeshaji wa teknolojia→Mageuzi ya fahari</td><td>Mafanikio ya kupanda kwa mara ya kwanza→Uanzishaji wa Jamhuri ya Kila Rangi</td><td>Uthibitisho wa kupanda kwa ustaarabu, mapambano ya kiolesura cha eneo la fahari</td></tr><tr><td>Enzi ya Sita</td><td>Enzi ya Jamhuri ya Kila Rangi</td><td>Mageuzi ya fahari</td><td>Uanzishaji wa Jamhuri ya Kila Rangi→Mwanzo wa uchunguzi kati ya viwango</td><td>Umoja wa mfumo wa kila rangi, usirikisho wa fahari ya pamoja</td></tr><tr><td>Enzi ya Saba</td><td>Enzi ya Uchunguzi kati ya Viwango</td><td>Mageuzi ya fahari→Usirikisho wa kati ya nyota</td><td>Mwanzo wa uchunguzi kati ya viwango→Ujenzi wa awali wa mtandao wa kati ya nyota</td><td>Ugunduzi mkubwa wa viwango, upanuzi wa mtandao wa nanga</td></tr><tr><td>Enzi ya Nane</td><td>Enzi ya Usirikisho wa kati ya Nyota</td><td>Usirikisho wa kati ya nyota</td><td>Ujenzi wa mtandao wa kati ya nyota→Kupanda kwa jumla kwa ulimwengu</td><td>Usirikisho wa ulimwengu wa kila rangi, kupanda kwa ulimwengu unaendelea</td></tr></tbody></table><h2 id="_3-muda-wa-kila-enzi-na-viwango-vya-muhimu" tabindex="-1">3. Muda wa Kila Enzi na Viwango vya Muhimu <a class="header-anchor" href="#_3-muda-wa-kila-enzi-na-viwango-vya-muhimu" aria-label="Permalink to &quot;3. Muda wa Kila Enzi na Viwango vya Muhimu&quot;">​</a></h2><p>Kwa kuwa Hengyuanzhou inajumuisha viwango vingi na kasi za muda zinazotofautiana kati ya viwango, muda wa enzi unategemea muda wa kiwango cha msingi:</p><table tabindex="0"><thead><tr><th>Enzi</th><th>Muda wa Kadiri</th><th>Kiwango cha Ufunuo wa Nanga</th><th>Ulinganifu wa Walinzi</th><th>Kiwango cha Daraja la Usirikisho</th></tr></thead><tbody><tr><td>Enzi ya Kabla ya Nanga</td><td>Haijulikani (taratibu ya mabilioni ya miaka)</td><td>0%</td><td>&lt;0.01%</td><td>&lt;10</td></tr><tr><td>Enzi ya Uamsho wa Nanga</td><td>Maelfu ya miaka</td><td>1%→10%</td><td>0.01%→1%</td><td>10→30</td></tr><tr><td>Kipindi cha Uanzishaji wa Mfumo wa Usirikisho</td><td>Karne</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>Enzi ya Kufungua na Kuwasha Mfumo</td><td>Karne</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>Enzi ya Kupanda kwa Mara ya Kwanza</td><td>Miongo michache</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>Enzi ya Jamhuri ya Kila Rangi</td><td>Karne</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>Enzi ya Uchunguzi kati ya Viwango</td><td>Maelfu ya miaka</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>Enzi ya Usirikisho wa kati ya Nyota</td><td>Inaendelea</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>Kiwango cha ufunuo wa nanga kinarejelea ulinganifu wa maeneo ndogo ya viwango ambapo vifaa vya nanga vimewekwa; ulinganifu wa walinzi unarejelea ulinganifu wa viumbe vilivyofunikwa na mfumo rasmi wa ulinzi; kiwango cha daraja la usirikisho ni kiwango cha jumla kinachopima kiwango cha usirikisho wa ustaarabu, na alama ya juu kabisa ni 100.</p><h2 id="_4-mantiki-ya-ndani-ya-mageuzi-ya-enzi" tabindex="-1">4. Mantiki ya Ndani ya Mageuzi ya Enzi <a class="header-anchor" href="#_4-mantiki-ya-ndani-ya-mageuzi-ya-enzi" aria-label="Permalink to &quot;4. Mantiki ya Ndani ya Mageuzi ya Enzi&quot;">​</a></h2><p>Mageuzi ya enzi za Hengyuanzhou sio mtiririko wa muda wa mstari, bali ni mchakato wa mageuzi wa pete inayopanda juu. Kila enzi linatatua utata kuu uliobaki kutoka enzi lililopita, wakati huo huo linaanza hali za maendeleo kwa enzi linalofuata:</p><ul><li>Utata kuu wa Enzi ya Kabla ya Nanga ni utata kati ya mauaji na usirikisho, ambao ukosefu wake ulisababisha lazima ya uamsho wa nanga</li><li>Enzi ya Uamsho wa Nanga ilitatua swali la &quot;je, nanga ipo&quot;, lakini ilikabiliwa na changamoto ya taasisi ya &quot;nanga inahudumia nani&quot;</li><li>Kipindi cha Uanzishaji wa Mfumo wa Usirikisho kilikamilisha ujenzi wa taasisi, lakini utawala wa rasilimali za ulinzi bado unazuia mageuzi ya umma</li><li>Enzi ya Kufungua na Kuwasha Mfumo ilivunja utawala wa ulinzi, lakini kuruka kwa uwezo wa mtu binafsi kuleta changamoto mpya za maadili na usalama</li><li>Enzi ya Kupanda kwa Mara ya Kwanza ilithibitisha uwezekano wa kupanda, lakini kupanda kwa kiwango kimoja hakikutoshi kuchochea mageuzi ya jumla ya ulimwengu</li><li>Enzi ya Jamhuri ya Kila Rangi iliunganisha mfumo wa ustaarabu, lakini bado kuna viwango vingi na rangi ambavyo havijawahi kuwasiliana katika ulimwengu</li><li>Enzi ya Uchunguzi kati ya Viwango ilipanua mipaka ya ustaarabu, lakini viwango vilivyotawanyika vinahitaji muunganisho wa kati ya nyota ulio karibu zaidi</li><li>Enzi ya Usirikisho wa kati ya Nyota hatimaye inaelekeza katika lengo la juu la kupanda kwa jumla la ulimwengu</li></ul><h2 id="_5-nafasi-ya-enzi-ya-sasa" tabindex="-1">5. Nafasi ya Enzi ya Sasa <a class="header-anchor" href="#_5-nafasi-ya-enzi-ya-sasa" aria-label="Permalink to &quot;5. Nafasi ya Enzi ya Sasa&quot;">​</a></h2><p>Kulingana na hali ya maendeleo ya sasa ya Hengyuanzhou, ustaarabu uko katika hatua muhimu ya mabadiliko kutoka Enzi ya Tatu (Kipindi cha Uanzishaji wa Mfumo wa Usirikisho) kwenda Enzi ya Nne (Enzi ya Kufungua na Kuwasha Mfumo). Mfumo wa usirikisho tayari umeatekelezwa katika viwango vikuu, kazi ya kufungua miitano mia tatu inaendelea kwa kasi, na mkakati wa kuwasha 20% umeingia katika hatua ya utekelezaji. Teknolojia kadhaa za msingi katika safu ya uhandisi wa sheria (injini ya kukisia matunda ya kuzidisha, kifaa cha sheria ya nafasi, mfumo wa kioo cha nakala) zimehamia kutoka maabara kwenda uzalishaji wa wingi.</p><p>Kazi kuu ya kipindi hiki cha mabadiliko ni: kuhakikisha kwamba kufunguliwa kwa miitano mia tatu kweli kunaleta manufaa kwa viumbe vyote, wakati huo huo kupitia mkakati wa kuwasha 20% kulelewa kundi la kwanza la walinzi wenye uwezo wa juu zaidi wa kiwango, na kukusanya nishati na uzoefu wa kutosha kwa kupanda kwa mara ya kwanza.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Jedwali la Jumla la Mgawanyo wa Enzi ni muundo wa mkubwa wa kuelewa mageuzi ya kihistoria ya Hengyuanzhou. Linapunguza historia ndefu ya ulimwengu kuwa enzi nane zenye mantiki ya ndani ya wazi, kila enzi ikiwa daraja la lazima la kupanda kwa jumla la ulimwengu. Hati zinazofuata zitaeleza kwa undani kila enzi na matukio muhimu ndani yake.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>71-Enzi ya Kabla ya Nanga</li><li>72-Enzi ya Uamsho wa Nanga</li><li>76-Alama ya Kupanda kwa Mara ya Kwanza</li></ul>',22)])])}const y=i(d,[["render",e]]);export{z as __pageData,y as default};
